#pragma once
// Shared POD layout for the per-version mapping tables generated by
// tools/genmaps/genmaps.py. Each generated TU (src/mappings/generated/mappings_1_21_N.cpp)
// defines four constexpr arrays sorted by FNV1a-64 key and exports one
// `constinit const VersionTable v_1_21_N`. src/mappings/generated/mappings_index.cpp
// then chains those exports into a version-name-keyed index.
//
// Runtime lookup: FNV1a-64 the canonical string, std::lower_bound over the
// sorted array. Everything lives in .rdata — zero heap, zero static-init cost.

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace vanta::mappings::gen {

struct ClassEntry {
    std::uint64_t     canonHash;   // fnv1a64(canonical short name)
    std::string_view  runtime;     // JNI slash form (e.g. "net/minecraft/class_310")
};

struct MemberEntry {
    std::uint64_t     ownerHash;   // fnv1a64(canonical owner name)
    std::uint64_t     nameHash;    // fnv1a64(canonical member name)
    std::string_view  name;        // runtime (intermediary) name
    std::string_view  desc;        // pre-remapped intermediary descriptor
};

struct ReverseClassEntry {
    std::uint64_t     runtimeHash; // fnv1a64(runtime slash name)
    std::string_view  canon;       // canonical short name
};

struct VersionTable {
    std::string_view         mcVersion;
    const ClassEntry*        classes;
    std::size_t              classCount;
    const MemberEntry*       methods;
    std::size_t              methodCount;
    const MemberEntry*       fields;
    std::size_t              fieldCount;
    const ReverseClassEntry* reverseClasses;
    std::size_t              reverseClassCount;
};

} // namespace vanta::mappings::gen
